<?php
require_once __DIR__ . '/../inc/billing_financials.php';
function ok($condition,$message){if(!$condition){fwrite(STDERR,"FAIL: $message\n");exit(1);}echo "PASS: $message\n";}
$pdo=new PDO('sqlite::memory:');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$pdo->exec("CREATE TABLE eventos(id INTEGER PRIMARY KEY,nombre TEXT,creado_por_admin_id INTEGER,borrado_en TEXT);CREATE TABLE tc_orders(id INTEGER PRIMARY KEY,request_id TEXT,state TEXT,evento_id INTEGER,ref TEXT,amount REAL,buyer_first TEXT,buyer_last TEXT,created_at TEXT,updated_at TEXT,payment_confirmed_at TEXT,payment_status TEXT,payment_provider TEXT,marketplace_fee REAL,ticket_subtotal REAL,service_fee_amount REAL,mp_cost_estimate_percent REAL);");
$pdo->exec("INSERT INTO eventos VALUES(1,'Evento A',10,NULL),(2,'Evento B',20,NULL);INSERT INTO tc_orders VALUES(1,'mp1','created',1,'r1',11000,'Ana','A','2026-09-01','2026-09-01','2026-09-01','confirmed','mercadopago',121.10,10000,1000,7.99),(2,'tc1','success',1,'r2',10000,'Beto','B','2026-09-02','2026-09-02','2026-09-02','confirmed','totalcoin',0,10000,0,0),(3,'m1','manual_confirmed',1,'r3',20000,'Caro','C','2026-09-03','2026-09-03','2026-09-03','confirmed','manual_transfer',0,NULL,0,0),(4,'p1','created',1,'r4',9000,'Dani','D','2026-09-04','2026-09-04',NULL,'pending','totalcoin',0,9000,0,0),(5,'x1','success',2,'r5',50000,'Otro','Admin','2026-09-05','2026-09-05','2026-09-05','confirmed','totalcoin',0,50000,0,0);");
$r=tickex_billing_report($pdo,10,false,array());
ok(count($r['recent'])===4,'an administrator only sees own event movements');ok(abs($r['summary']['gross']-41000)<.01,'confirmed gross excludes pending and other administrators');ok(abs($r['summary']['service_fee']-1000)<.01,'buyer service charge is reported separately');ok(abs($r['summary']['provider_cost']-1178.90)<.01,'provider costs combine Mercado Pago estimate and TotalCoin three percent');ok(abs($r['summary']['platform_fee']-121.10)<.01,'Tickex marketplace fee is separated');ok(abs($r['summary']['organizer_net']-39700)<.01,'organizer estimated net is calculated consistently');ok($r['summary']['confirmed']===3&&$r['summary']['pending']===1,'movement states are counted');
$f=tickex_billing_report($pdo,10,false,array('provider'=>'manual_transfer','status'=>'confirmed'));ok(count($f['recent'])===1&&abs($f['summary']['gross']-20000)<.01,'provider and status filters work together');$s=tickex_billing_report($pdo,99,true,array());ok(abs($s['summary']['gross']-91000)<.01,'superadministrator can review the platform total');echo "ALL BILLING FINANCIAL TESTS PASSED\n";
